using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Object=UnityEngine.Object;
public static class AuditGeneratedModelPlacements{
 static string Path(Transform t)=>t.parent==null?t.name:Path(t.parent)+"/"+t.name;
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Idle only");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene");var setup=EditorSceneManager.GetSceneManagerSetup();var result=new List<object>();try{foreach(var name in new[]{"Jamsil","ShoeTower"}){var scene=EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/"+name+".unity");var meshes=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(m=>m.sharedMesh!=null&&AssetDatabase.GetAssetPath(m.sharedMesh).EndsWith(".fbx",StringComparison.OrdinalIgnoreCase)).ToArray();result.Add(new{scene=name,assets=meshes.GroupBy(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).Select(g=>new{asset=g.Key,instances=g.Select(m=>new{path=Path(m.transform),m.gameObject.activeInHierarchy,position=new[]{m.transform.position.x,m.transform.position.y,m.transform.position.z}}).ToArray()}).ToArray()});}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return new{utc=DateTime.UtcNow.ToString("o"),savedScenes=result,readOnly=true};}
}
